import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, vec4, smoothstep, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Mesh, PlaneGeometry, Group, Color, SRGBColorSpace, DoubleSide } = THREE;

  const group = new Group();
  group.name = 'hub-pricing-quote';

  const colors = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // ---- Backdrop stage (vertical gradient + faint accent bloom, <10% frame) ----
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide, toneMapped: false });
  {
    const v = uv().y;
    const base = mix(vec3(colors.surface), vec3(colors.ink), v);
    const cx = uv().x.sub(0.5).abs();
    const horiz = smoothstep(0.5, 0.0, cx);
    const vert = smoothstep(0.4, 0.0, v);
    const accentAmt = horiz.mul(vert).mul(0.05);
    backdropMat.colorNode = mix(base, vec3(colors.accent), accentAmt);
  }
  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  const cardW = 2.6;
  const cardH = 1.625; // 512×320 aspect

  // ---- Contact shadow behind card ----
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false, toneMapped: false });
  shadowMat.opacity = 0;
  {
    const d = uv().sub(0.5).length();
    const a = smoothstep(0.5, 0.0, d).mul(0.45);
    shadowMat.colorNode = vec4(0, 0, 0, a);
  }
  const shadow = new Mesh(new PlaneGeometry(cardW * 1.25, cardH * 1.25), shadowMat);
  shadow.position.z = -0.05;
  group.add(shadow);

  // ---- Machined bezel (darker frame just behind card edge) ----
  const bezelMat = new MeshBasicNodeMaterial({ color: new Color('#0e0e14'), toneMapped: false });
  const bezel = new Mesh(new PlaneGeometry(cardW + 0.02, cardH + 0.02), bezelMat);
  bezel.position.z = -0.02;
  group.add(bezel);

  // ---- Accent rim (edge that ignites on focus/hover) ----
  const rimMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0,
    toneMapped: false,
    side: DoubleSide,
    depthWrite: false,
  });
  const rim = new Mesh(new PlaneGeometry(cardW + 0.08, cardH + 0.08), rimMat);
  rim.position.z = -0.01;
  group.add(rim);

  // ---- Main quote card (textured plane) ----
  const cardMat = new MeshBasicNodeMaterial({ transparent: true, toneMapped: false });
  cardMat.opacity = 0;
  cardMat.colorNode = vec3(0.12, 0.12, 0.16); // placeholder until texture arrives
  const cardMesh = new Mesh(new PlaneGeometry(cardW, cardH), cardMat);
  cardMesh.position.z = 0.0;
  group.add(cardMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      cardMat.colorNode = texture(tex);
      cardMat.needsUpdate = true;
    });
  }

  // ---- Entrance (rise-in + weighted-settle, rim ignition pop) ----
  const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });
  tl.from(cardMesh.position, { y: 0.45, duration: 0.7 }, 0)
    .to(cardMat, { opacity: 1, duration: 0.6 }, 0)
    .from(shadow.scale, { x: 0.6, y: 0.6, duration: 0.7 }, 0)
    .to(shadowMat, { opacity: 1, duration: 0.7 }, 0)
    .to(cardMesh.scale, { x: 1.04, y: 1.04, duration: 0.5, ease: 'power2.out' }, 0.55)
    .to(cardMesh.scale, { x: 1.0, y: 1.0, duration: 0.45, ease: 'power4.out' }, 1.0)
    .to(rimMat, { opacity: 1, duration: 0.35, ease: 'power2.out' }, 0.55)
    .to(rimMat, { opacity: 0, duration: 0.5, ease: 'power2.out' }, 0.9);

  // ---- Interactions ----
  const liftY = 0.15;
  let hovered = false;
  let focused = false;

  function applyAccent() {
    const on = hovered || focused;
    gsap.to(rimMat, { opacity: on ? 1 : 0, duration: 0.3, ease: 'power2.out' });
    gsap.to(rim.scale, {
      x: on ? 1.06 : 1.0,
      y: on ? 1.06 : 1.0,
      duration: 0.35,
      ease: 'power3.out',
    });
  }

  function applyLift() {
    const y = hovered ? liftY : 0;
    gsap.to(cardMesh.position, { y, duration: 0.5, ease: 'power3.out' });
    gsap.to(shadow.position, { y, duration: 0.5, ease: 'power3.out' });
    gsap.to(bezel.position, { y, duration: 0.5, ease: 'power3.out' });
    gsap.to(rim.position, { y, duration: 0.5, ease: 'power3.out' });
  }

  group.userData.handlers = {
    hover: (enter) => {
      hovered = !!enter;
      applyLift();
      applyAccent();
    },
    focus: (enter) => {
      focused = !!enter;
      applyAccent();
    },
    click: () => {
      gsap.to(cardMesh.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
        yoyo: true,
        repeat: 1,
      });
      ctx.emit('hub-pricing.select', { source: 'pricing-quote' });
    },
  };

  // ---- Cinematic primitive: parallax-scroll (scroll trigger) ----
  let primCleanup = null;
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    const r = ctx.primitives['parallax-scroll'](group, { intensity: 0.25 });
    primCleanup = r && typeof r.cleanup === 'function' ? r.cleanup : null;
  }

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(cardMesh.position);
    gsap.killTweensOf(cardMesh.scale);
    gsap.killTweensOf(shadow.position);
    gsap.killTweensOf(shadow.scale);
    gsap.killTweensOf(shadowMat);
    gsap.killTweensOf(bezel.position);
    gsap.killTweensOf(rimMat);
    gsap.killTweensOf(rim.scale);
    gsap.killTweensOf(rim.position);
    if (primCleanup) primCleanup();
    backdropMat.dispose();
    shadowMat.dispose();
    bezelMat.dispose();
    rimMat.dispose();
    cardMat.dispose();
    backdrop.geometry.dispose();
    shadow.geometry.dispose();
    bezel.geometry.dispose();
    rim.geometry.dispose();
    cardMesh.geometry.dispose();
  };

  return group;
}
